<?php
declare(strict_types=1);
require __DIR__.'/storefront-views.php';header('Content-Type: text/html; charset=utf-8');header('Cache-Control: private, no-cache');header('Vary: Cookie');
$data=storefront_data();$slug=$_GET['slug']??'';$product=null;if(is_string($slug)&&strlen($slug)<200)foreach($data['products'] as $p)if($p['id']===$slug){$product=$p;break;}
