if(is_numeric($p['priceFrom'][$currency]??null)&&$p['priceFrom'][$currency]>0)$schema['offers']=['@type'=>'AggregateOffer','priceCurrency'=>$currency,'lowPrice'=>$p['priceFrom'][$currency],'url'=>$config['origin'].$path];
?><!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><?=sf_meta($p['title'].' оптом — Lucky',$metaDescription,$path,$photo,'product')?><link rel="icon" href="/clover.svg"><link rel="stylesheet" href="/styles.css?v=leads-seo-v1"><link rel="stylesheet" href="/leads.css?v=1"><script type="application/ld+json"><?=sf_json($schema)?></script></head><body>
<header class="site-header"><a class="brand" href="/"><img class="brand-logo" src="/lucky-logo.svg" alt="Lucky"><span class="brand-mode">ОПТОМ</span></a><a href="/#catalog">Все товары</a></header>
<main class="product-page"><nav aria-label="Хлебные крошки"><a href="/">Главная</a> / <a href="/#catalog">Каталог</a> / <?=sf_e($p['title'])?></nav><div class="product-page-layout"><div class="product-page-photos"><?php foreach(array_slice($p['photos']??[],0,5) as $image):?><img src="<?=sf_e(storefront_image($image))?>" alt="<?=sf_e($p['title'])?>" loading="lazy"><?php endforeach;?></div><section><p class="section-kicker dark"><?=sf_e($p['brand']??'Lucky')?></p><h1><?=sf_e($p['title'])?></h1><p><?=sf_e(sf_sport($p,$data['categories']))?></p><p>Артикул: <?=sf_e($p['article']??$p['id'])?></p><label>Валюта <select id="productCurrency" aria-label="Валюта цены"><?php foreach(['KZT','RUB','USD'] as $c):?><option value="<?=$c?>"<?=$currency===$c?' selected':''?>><?=$c?></option><?php endforeach;?></select></label><p class="product-page-price" data-prices="<?=sf_e(json_encode($p['priceFrom']??[]))?>"><?=sf_e(sf_price($p,$currency))?></p><button class="dialog-primary" type="button" data-request-product="<?=sf_e($p['id'])?>" data-request-title="<?=sf_e($p['title'])?>">Запросить оптовую цену</button><h2>Описание</h2><p class="product-page-description"><?=nl2br(sf_e($description))?></p><h2>Размеры</h2><p><?=sf_e(implode(', ',array_map(fn($v)=>is_array($v)?($v['name']??$v['techSize']??''):strval($v),$p['sizes']??[]))?:'Размеры уточнит менеджер')?></p><?php if(!empty($p['colors'])):?><h2>Цвета</h2><p><?=sf_e(implode(', ',$p['colors']))?></p><?php endif;?></section></div><?=sf_terms()?></main><?=sf_form()?>
<footer class="product-page-footer"><a href="/privacy.php">Обработка персональных данных</a> · <a href="<?=$config['whatsapp']?>">WhatsApp</a> · <a href="<?=$config['telegram']?>">Telegram</a></footer><script type="module" src="/leads.js?v=1"></script><script type="module" src="/metrika.js?v=1"></script></body></html>
